+    <maven.compile.target>1.8</maven.compile.target>
     <math.pmd.version>2.7.1</math.pmd.version>
     <math.findbugs.version>2.5.1</math.findbugs.version>
     <math.checkstyle.version>2.9.1</math.checkstyle.version>
diff --git a/src/main/java/org/apache/commons/math3/util/MathArrays.java b/src/main/java/org/apache/commons/math3/util/MathArrays.java
index 325fd9430..d6d7432c5 100644
--- a/src/main/java/org/apache/commons/math3/util/MathArrays.java
+++ b/src/main/java/org/apache/commons/math3/util/MathArrays.java
@@ -843,18 +843,26 @@ public class MathArrays {


         final double prodHighCur = prodHigh[0];
-        double prodHighNext = prodHigh[1];
-        double sHighPrev = prodHighCur + prodHighNext;
-        double sPrime = sHighPrev - prodHighNext;
-        double sLowSum = (prodHighNext - (sHighPrev - sPrime)) + (prodHighCur - sPrime);
-
-        final int lenMinusOne = len - 1;
-        for (int i = 1; i < lenMinusOne; i++) {
-            prodHighNext = prodHigh[i + 1];
-            final double sHighCur = sHighPrev + prodHighNext;
-            sPrime = sHighCur - prodHighNext;
-            sLowSum += (prodHighNext - (sHighCur - sPrime)) + (sHighPrev - sPrime);
-            sHighPrev = sHighCur;
+        double sHighPrev;
+        double sLowSum;
+
+        if (len == 1) {
+            sHighPrev = prodHighCur;
+            sLowSum = 0;
+        } else {
+            double prodHighNext = prodHigh[1];
+            sHighPrev = prodHighCur + prodHighNext;
+            double sPrime = sHighPrev - prodHighNext;
+            sLowSum = (prodHighNext - (sHighPrev - sPrime)) + (prodHighCur - sPrime);
+
+            final int lenMinusOne = len - 1;
+            for (int i = 1; i < lenMinusOne; i++) {
+                prodHighNext = prodHigh[i + 1];
+                final double sHighCur = sHighPrev + prodHighNext;
+                sPrime = sHighCur - prodHighNext;
+                sLowSum += (prodHighNext - (sHighCur - sPrime)) + (sHighPrev - sPrime);
+                sHighPrev = sHighCur;
+            }
         }

         double result = sHighPrev + (prodLowSum + sLowSum);
